modelica_source:
model Mass1
 extends Modelica.Mechanics.Translational.Examples.Damper(mass1(final m=0,v(fixed=false),s(fixed=false)));
end Mass1;
model Mass2
 extends Modelica.Mechanics.Translational.Examples.Damper(mass2(final m=0,v(fixed=false),s(fixed=false)));
end Mass2;
model Mass3
 extends Modelica.Mechanics.Translational.Examples.Damper(mass3(final m=0,v(fixed=false),s(fixed=false)));
end Mass3;
model Arrows
 extends Modelica.Mechanics.Translational.Examples.WhyArrows(inertia2(final m=0,v(fixed=false),s(fixed=false)));
end Arrows;
model ChuaC1
 extends Modelica.Electrical.Analog.Examples.ChuaCircuit(C1(final C=0,v(fixed=false)),C2(v(fixed=false)),L(i(fixed=false)));
end ChuaC1;
model ChuaC2
 extends Modelica.Electrical.Analog.Examples.ChuaCircuit(C2(final C=0,v(fixed=false)),C1(v(fixed=false)),L(i(fixed=false)));
end ChuaC2;
model Shaft
 extends Modelica.Mechanics.Rotational.Examples.ElasticBearing(shaft(final J=0),springDamper(phi_rel(fixed=false),w_rel(fixed=false)));
end Shaft;
model Ramp
 extends Modelica.Clocked.Examples.SimpleControlledDrive.Continuous(ramp(final duration=0));
end Ramp;
model ParallelC2
 extends Modelica.Electrical.Analog.Examples.ParallelResonance(capacitor2(final C=0,v(fixed=false)),inductor2(i(fixed=false)));
end ParallelC2;
model MachineNominal
 parameter Modelica.Electrical.Machines.Utilities.SynchronousMachineData d(SNominal=30E3,VsNominal=100,fsNominal=50,IeOpenCircuit=10,x0=0.1,xd=1.6,xq=1.6,xdTransient=0.1375,xdSubtransient=0.121428571,xqSubtransient=0.148387097,Ta=0.014171268,Td0Transient=0.261177343,Td0Subtransient=0.006963029,Tq0Subtransient=0.123345081,TsSpecification=293.15,TsRef=293.15,alpha20s=0,TrSpecification=293.15,TrRef=293.15,alpha20r=0,TeSpecification=293.15,TeRef=293.15,alpha20e=0);
 Real y;
equation
 y=d.xe+d.xrd+d.xrq;
end MachineNominal;
model MachineXd
 extends MachineNominal(d(final xd=0.1375));
end MachineXd;
model MachineXdTransient
 extends MachineNominal(d(final xdTransient=0.121428571));
end MachineXdTransient;
model MachineXq
 extends MachineNominal(d(final xq=0.148387097));
end MachineXq;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CONTROL Mass1\n"); simulate(Mass1,stopTime=0.5,numberOfIntervals=100,outputFormat="csv");getErrorString();
print("AUDIT_CONTROL Mass2\n"); simulate(Mass2,stopTime=0.5,numberOfIntervals=100,outputFormat="csv");getErrorString();
print("AUDIT_CONTROL Mass3\n"); simulate(Mass3,stopTime=0.5,numberOfIntervals=100,outputFormat="csv");getErrorString();
print("AUDIT_CONTROL Arrows\n"); simulate(Arrows,stopTime=0.5,numberOfIntervals=100,outputFormat="csv");getErrorString();
print("AUDIT_CONTROL ChuaC1\n"); simulate(ChuaC1,stopTime=0.5,numberOfIntervals=100,outputFormat="csv");getErrorString();
print("AUDIT_CONTROL ChuaC2\n"); simulate(ChuaC2,stopTime=0.5,numberOfIntervals=100,outputFormat="csv");getErrorString();
print("AUDIT_CONTROL Shaft\n"); simulate(Shaft,stopTime=0.5,numberOfIntervals=100,outputFormat="csv");getErrorString();
print("AUDIT_CONTROL Ramp\n"); simulate(Ramp,stopTime=0.5,numberOfIntervals=100,outputFormat="csv");getErrorString();
print("AUDIT_CONTROL ParallelC2\n"); simulate(ParallelC2,stopTime=0.5,numberOfIntervals=100,outputFormat="csv");getErrorString();
print("AUDIT_CONTROL MachineNominal\n"); simulate(MachineNominal,stopTime=0.5,numberOfIntervals=100,outputFormat="csv");getErrorString();
print("AUDIT_CONTROL MachineXd\n"); simulate(MachineXd,stopTime=0.5,numberOfIntervals=100,outputFormat="csv");getErrorString();
print("AUDIT_CONTROL MachineXdTransient\n"); simulate(MachineXdTransient,stopTime=0.5,numberOfIntervals=100,outputFormat="csv");getErrorString();
print("AUDIT_CONTROL MachineXq\n"); simulate(MachineXq,stopTime=0.5,numberOfIntervals=100,outputFormat="csv");getErrorString();
